using System;using System.IO;using System.Linq;using System.Collections.Generic;using Newtonsoft.Json;using Newtonsoft.Json.Linq;using Orbit;
class StateRecoveryTests {
 static int count;static string root=Path.Combine(Path.GetTempPath(),"orbit-state-"+Guid.NewGuid());static string A=Guid.NewGuid().ToString(),B=Guid.NewGuid().ToString();
 static void Check(bool value,string name){if(!value)throw new Exception(name);Console.WriteLine("PASS "+(++count)+" "+name);}
 static void Fails(Action action,string name){try{action();}catch{Check(true,name);return;}throw new Exception(name);}
 static JObject Job(string id=null)=>JObject.FromObject(new InstallJob{id=id??A,gameId=B,appId="1091500",name="Игра",store="steam",path=Path.Combine(root,"Steam"),state="handed",createdAt=DateTime.UtcNow});
 static LauncherStateFile<JObject> Prefs(string name,int max=2097152)=>new LauncherStateFile<JObject>(Path.Combine(root,name),max,LauncherState.Preferences,()=>new JObject());
 static LauncherStateFile<List<InstallJob>> Jobs(string name)=>new LauncherStateFile<List<InstallJob>>(Path.Combine(root,name),8388608,LauncherState.Downloads,()=>new List<InstallJob>());
 static void Main(){Directory.CreateDirectory(root);try{
  var value=LauncherState.Downloads(new JArray(JValue.CreateNull(),Job()).ToString());Check(value.repaired&&value.value.Count==1,"null job cannot crash startup; valid job survives");
  value=LauncherState.Downloads(new JArray(Job(),Job(),JObject.Parse("{id:'broken'}")).ToString());Check(value.repaired&&value.value.Count==1,"duplicate and malformed jobs isolated");
  var job=Job();job["createdAt"]="invalid";Check(LauncherState.Downloads(new JArray(job,Job()).ToString()).value.Count==1,"bad date in one job does not discard other jobs");
  job=Job();job["state"]="unknown";job["percent"]=double.PositiveInfinity;var clean=LauncherState.Downloads(new JArray(job).ToString()).value.Single();Check(clean.state=="attention"&&clean.percent==null,"unknown state and impossible progress sanitized");
  job=Job();job["store"]="other";Check(LauncherState.Downloads(new JArray(job).ToString()).value.Count==0,"unknown store cannot enter telemetry");
  Fails(()=>LauncherState.Downloads("{}"),"wrong download root rejected");Fails(()=>LauncherState.Downloads("[] []"),"trailing JSON rejected");
  var prefs=LauncherState.Preferences(new JObject{["backgroundClients"]="bad",["view"]=new JObject(),["groups"]=new JObject{[B]="my group"},["preferred"]=new JObject{["my group"]=B},["customExtension"]=42}.ToString());
  Check(prefs.repaired&&prefs.value["backgroundClients"]==null&&prefs.value["view"]==null,"invalid booleans and view repaired without startup cast exception");Check((string)prefs.value["groups"][B]=="my group"&&(string)prefs.value["preferred"]["my group"]==B,"valid grouping and preferred copy preserved");Check((int)prefs.value["customExtension"]==42,"unrelated preference fields preserved");
  var current=JObject.Parse("{backgroundClients:true,lowEffects:false}");Fails(()=>LauncherState.Patch(current,JObject.Parse("{lowEffects:true,backgroundClients:'bad'}")),"invalid mixed patch rejected");Check((bool)current["lowEffects"]==false,"rejected patch cannot partially mutate memory");var next=LauncherState.Patch(current,JObject.Parse("{lowEffects:true}"));Check((bool)next["lowEffects"]&&!(bool)current["lowEffects"],"valid patch detached before persistence");
  var path=Path.Combine(root,"downloads.json");File.WriteAllText(path,new JArray(JValue.CreateNull(),Job()).ToString());var original=File.ReadAllText(path);var loaded=Jobs("downloads.json");Check(!loaded.ReadOnly&&loaded.Value.Count==1&&loaded.Warning!=null,"recover valid records from damaged list");var retained=Directory.GetFiles(root,"downloads.json.invalid-*").Single();Check(File.ReadAllText(retained)==original,"original damaged list retained byte-for-byte");loaded.Save(loaded.Value);Check(!Jobs("downloads.json").ReadOnly&&Jobs("downloads.json").Value.Count==1,"repaired history survives restart");
  var file=Path.Combine(root,"preferences.json");File.WriteAllText(file,"{broken");File.WriteAllText(file+".bak","{view:'list',lowEffects:true}");var backed=Prefs("preferences.json");Check(!backed.ReadOnly&&(bool)backed.Value["lowEffects"],"valid backup recovers syntax damage");backed.Save(backed.Value);Check(File.ReadAllText(file+".bak").Contains("lowEffects"),"first recovered save preserves valid backup");Check(Directory.GetFiles(root,"preferences.json.invalid-*").Length==1,"broken primary preserved before replacement");
  File.WriteAllText(file,"bad");File.WriteAllText(file+".bak","bad-backup");var blocked=Prefs("preferences.json");Check(blocked.ReadOnly&&blocked.Warning!=null,"two damaged copies allow launch with read-only defaults");Fails(()=>blocked.Save(new JObject()),"unrecoverable file protected from overwrite");Check(File.ReadAllText(file)=="bad"&&File.ReadAllText(file+".bak")=="bad-backup","failed recovery retains both originals");
  File.WriteAllText(Path.Combine(root,"large.json"),new string('x',100));File.WriteAllText(Path.Combine(root,"large.json.bak"),"{}");var large=Prefs("large.json",32);Check(large.ReadOnly&&new FileInfo(Path.Combine(root,"large.json")).Length==100,"oversized original not silently overwritten");
  File.WriteAllText(Path.Combine(root,"only-backup.json.bak"),"{view:'list'}");var onlyBackup=Prefs("only-backup.json");Check(!onlyBackup.ReadOnly&&(string)onlyBackup.Value["view"]=="list"&&onlyBackup.Warning=="Данные восстановлены из резервной копии.","missing primary recovers backup without claiming an original copy");onlyBackup.Save(onlyBackup.Value);Check(File.Exists(Path.Combine(root,"only-backup.json"))&&File.Exists(Path.Combine(root,"only-backup.json.bak")),"backup-only recovery creates primary and preserves backup");
  var missing=Prefs("new.json");Check(!missing.ReadOnly&&missing.Warning==null,"fresh install has writable defaults");missing.Save(JObject.Parse("{view:'grid'}"));Check((string)Prefs("new.json").Value["view"]=="grid","atomic preference write persists");
  var failure=Prefs("failure.json");Directory.CreateDirectory(Path.Combine(root,"failure.json"));Fails(()=>failure.Save(JObject.Parse("{view:'list'}")),"write failure is surfaced");Check(failure.Value.Count==0,"failed persistence leaves prior in-memory state");Check(!Directory.GetFiles(root,"*.tmp-*",SearchOption.AllDirectories).Any(),"temporary files cleaned after write failure");
  Console.WriteLine("State recovery: "+count+" checks passed.");
 }finally{Directory.Delete(root,true);}}
}
